13	// ============================================================
14	// Elementwise 算子 op_host 模板
15	// 适用: ReLU, GELU, Add, Mul 等逐元素算子
16	// 使用: 复制到 csrc/ops/<op_name>/op_host/<op_name>.cpp，
17	//       替换 <op_name>/<OpName>/<dtype> 等占位符
18	// ============================================================
19	
20	#include "torch_kernel_helper.h"
21	#include "tiling/platform/platform_ascendc.h"
22	#include "aclrtlaunch_<op_name>.h"
23	
24	namespace ascend_kernel {
25	
26	constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
27	
28	at::Tensor <op_name>(const at::Tensor &self /* , 其他输入参数 */)
29	{
30	    // ---- 输入校验 ----
31	    TORCH_CHECK(self.scalar_type() == at::kHalf || self.scalar_type() == at::kFloat,
32	                "<op_name>: only float16 and float32 are supported, got ", self.scalar_type());
33	
34	    at::Tensor output = at::empty_like(self);
35	
36	    int64_t totalLength = self.numel();
37	    if (totalLength == 0) {
38	        return output;
39	    }
40	
41	    int64_t dtypeSize = self.element_size();
42	
43	    // ---- 获取硬件参数 ----
44	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
45	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
46	    uint64_t ubSize;
47	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
48	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
49	
50	    // ---- Block 级 tiling (核间切分, Cache Line 对齐) ----
51	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
52	    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
53	                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;
54	
55	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
56	    int64_t formerNum = usedCoreNum - 1;
57	    int64_t formerLength = totalLengthCoreAlign;
58	    int64_t tailLength = totalLength - formerNum * formerLength;
59	
60	    // ---- UB 级 tiling (核内切分) ----
61	    // bufferCoefficient = 每元素在 UB 中总占用字节, 从设计文档 UB 分配表推导
62	    // 示例: 单输入单输出 + double buffer
63	    //   fp16: 2 queues * 2(double buf) * 2B = 8
64	    //   fp32: 2 queues * 2(double buf) * 4B = 16
65	    int64_t bufferCoefficient = dtypeSize * 4; // <-- 根据实际 UB 分配表修改
66	    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
67	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
68	    if (dtypeSize == 0) { dtypeSize = 1; }
69	    int64_t alignElements = 32 / dtypeSize;
70	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
71	
72	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
73	
74	    EXEC_KERNEL_CMD(<op_name>, blockDim,
75	                    self, output,
76	                    formerNum, formerLength, tailLength, tileLength, dtypeSize);
77	
78	    return output;
79	}
80	
81	}  // namespace ascend_kernel
