// ============================================================
// Spence (Dilogarithm) 算子 op_kernel
// 使用算术mask替代Compare/Select避免Ascend910B3兼容性问题
// ============================================================

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// 常量
constexpr float EPS = 1e-10f;
constexpr float PI_SQ_DIV_6 = 1.6449340668482264f;
constexpr float PI_SQ_DIV_3 = 3.289868133696453f;
constexpr float HALF = 0.5f;
constexpr float ONE = 1.0f;

// 多项式系数 c_k = 1/(k+1)^2，共20项
constexpr float COEFFS[20] = {
    1.0f,           // c_0  = 1/1^2
    0.25f,          // c_1  = 1/4
    0.111111111f,   // c_2  = 1/9
    0.0625f,        // c_3  = 1/16
    0.04f,          // c_4  = 1/25
    0.027777778f,   // c_5  = 1/36
    0.020408163f,   // c_6  = 1/49
    0.015625f,      // c_7  = 1/64
    0.012345679f,   // c_8  = 1/81
    0.01f,          // c_9  = 1/100
    0.008264463f,   // c_10 = 1/121
    0.006944444f,   // c_11 = 1/144
    0.005917160f,   // c_12 = 1/169
    0.005102041f,   // c_13 = 1/196
    0.004444444f,   // c_14 = 1/225
    0.00390625f,    // c_15 = 1/256
    0.003460208f,   // c_16 = 1/289
    0.003086420f,   // c_17 = 1/324
    0.002770083f,   // c_18 = 1/361
    0.0025f         // c_19 = 1/400
};

template <typename T>
class KernelSpence {
public:
    __aicore__ inline KernelSpence() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
        }

        this->tileLength = tileLength;

        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
        // 8 TBuf<float> 用于中间计算
        pipe.InitBuffer(tmpBuf0, tileLength * sizeof(float));
        pipe.InitBuffer(tmpBuf1, tileLength * sizeof(float));
        pipe.InitBuffer(tmpBuf2, tileLength * sizeof(float));
        pipe.InitBuffer(tmpBuf3, tileLength * sizeof(float));
        pipe.InitBuffer(tmpBuf4, tileLength * sizeof(float));
        pipe.InitBuffer(tmpBuf5, tileLength * sizeof(float));
        pipe.InitBuffer(tmpBuf6, tileLength * sizeof(float));
        pipe.InitBuffer(tmpBuf7, tileLength * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tileNum > 0) {
            CopyIn(tileNum - 1, alignedTailLen);
            Compute(tileNum - 1, alignedTailLen);
            CopyOut(tileNum - 1, alignedTailLen);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        AscendC::DataCopy(xLocal, xGm[progress * this->tileLength], curTileLength);
        inQueueX.EnQue(xLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();

        int32_t count = static_cast<int32_t>(curTileLength);

        // 获取所有中间计算缓冲区 (8x float32)
        AscendC::LocalTensor<float> buf0 = tmpBuf0.Get<float>();
        AscendC::LocalTensor<float> buf1 = tmpBuf1.Get<float>();
        AscendC::LocalTensor<float> buf2 = tmpBuf2.Get<float>();
        AscendC::LocalTensor<float> buf3 = tmpBuf3.Get<float>();
        AscendC::LocalTensor<float> buf4 = tmpBuf4.Get<float>();
        AscendC::LocalTensor<float> buf5 = tmpBuf5.Get<float>();
        AscendC::LocalTensor<float> buf6 = tmpBuf6.Get<float>();
        AscendC::LocalTensor<float> buf7 = tmpBuf7.Get<float>();

        if constexpr (sizeof(T) == sizeof(float)) {
            // float32: 复制输入到 buf0
            AscendC::Adds(buf0, xLocal, 0.0f, count);  // buf0 = x
        } else {
            // float16: 升精度到 float32
            AscendC::Cast(buf0, xLocal, AscendC::RoundMode::CAST_NONE, count);
        }

        // ===== Step 1: small = Min(x, 1/max(x, eps)) =====
        AscendC::Maxs(buf1, buf0, EPS, count);          // buf1 = max(x, eps)
        AscendC::Reciprocal(buf1, buf1, count);          // buf1 = 1/x
        AscendC::Min(buf2, buf0, buf1, count);           // buf2 = small = min(x, 1/x)

        // buf2 holds 'small' throughout. buf0 holds 'x' throughout.

        // ===== Step 2: a = Min(small, 1-small), oneMinusSmall = 1-small =====
        AscendC::Muls(buf3, buf2, -1.0f, count);        // buf3 = -small
        AscendC::Adds(buf3, buf3, ONE, count);           // buf3 = 1-small  (oneMinusSmall)
        AscendC::Min(buf4, buf2, buf3, count);           // buf4 = a = min(small, 1-small)

        // buf3: oneMinusSmall, buf4: a (in [0, 0.5])

        // ===== Step 3: Horner polynomial P(a) = sum c_k * a^k =====
        AscendC::Duplicate(buf5, COEFFS[19], count);     // buf5 = acc = c_19
        for (int k = 18; k >= 0; --k) {
            AscendC::Mul(buf1, buf4, buf5, count);       // buf1 = a * acc (reuse buf1 as prod)
            AscendC::Adds(buf5, buf1, COEFFS[k], count); // buf5 = c_k + a*acc
        }
        // poly_val = a * P(a) = a * acc
        AscendC::Mul(buf5, buf4, buf5, count);           // buf5 = polyVal = Spence(a)

        // buf5: polyVal (Spence(a))

        // ===== Step 4: [0.5, 1] Euclidean reflection =====
        // mask_half = (max(small,0.5)-0.5) / (max(small,0.5)-min(small,0.5)+eps)
        AscendC::Maxs(buf1, buf2, HALF, count);          // buf1 = xH_half = max(small, 0.5)
        AscendC::Mins(buf6, buf2, HALF, count);          // buf6 = xL_half = min(small, 0.5)

        AscendC::Sub(buf4, buf1, buf6, count);           // buf4 = xH - xL (reuse buf4)
        AscendC::Adds(buf4, buf4, EPS, count);           // buf4 = den = xH - xL + eps

        AscendC::Adds(buf1, buf1, -HALF, count);         // buf1 = num = xH - 0.5
        AscendC::Div(buf1, buf1, buf4, count);           // buf1 = maskHalf = num/den

        // buf1: maskHalf

        // ln_prod = ln(max(small,eps)) * ln(max(oneMinusSmall,eps))
        AscendC::Maxs(buf6, buf2, EPS, count);           // buf6 = max(small, eps)
        AscendC::Ln(buf6, buf6, count);                  // buf6 = ln(small)
        AscendC::Maxs(buf4, buf3, EPS, count);           // buf4 = max(oneMinusSmall, eps) (reuse buf4)
        AscendC::Ln(buf4, buf4, count);                  // buf4 = ln(oneMinusSmall)
        AscendC::Mul(buf7, buf6, buf4, count);           // buf7 = ln(small)*ln(oneMinusSmall) = lnProd

        // correction_half = PI_SQ_DIV_6 - lnProd - 2*polyVal
        AscendC::Muls(buf6, buf5, -2.0f, count);         // buf6 = -2*polyVal (reuse buf6)
        AscendC::Sub(buf6, buf6, buf7, count);           // buf6 = -2*polyVal - lnProd
        AscendC::Adds(buf7, buf6, PI_SQ_DIV_6, count);   // buf7 = correctionHalf

        // Spence_01 = polyVal + maskHalf * correctionHalf
        AscendC::Mul(buf6, buf1, buf7, count);           // buf6 = maskHalf * correctionHalf (reuse buf6)
        AscendC::Add(buf7, buf5, buf6, count);           // buf7 = Spence_01

        // buf7: Spence_01

        // ===== Step 5: x > 1 global reflection =====
        // mask_gt1 = (max(x,1.0)-1.0) / (max(x,1.0)-min(x,1.0)+eps)
        AscendC::Maxs(buf1, buf0, ONE, count);           // buf1 = xH_gt1 = max(x, 1.0)
        AscendC::Mins(buf3, buf0, ONE, count);           // buf3 = xL_gt1 = min(x, 1.0)

        AscendC::Sub(buf4, buf1, buf3, count);           // buf4 = xH - xL
        AscendC::Adds(buf4, buf4, EPS, count);           // buf4 = den

        AscendC::Adds(buf1, buf1, -ONE, count);          // buf1 = num = xH - 1.0
        AscendC::Div(buf1, buf1, buf4, count);           // buf1 = maskGt1

        // ln_x_sq = ln(max(x, eps))^2
        AscendC::Maxs(buf3, buf0, EPS, count);           // buf3 = max(x, eps)
        AscendC::Ln(buf3, buf3, count);                  // buf3 = ln(x)
        AscendC::Mul(buf3, buf3, buf3, count);           // buf3 = ln_x_sq

        // correction_gt1 = PI_SQ_DIV_3 - 0.5*ln_x_sq - 2*Spence_01
        AscendC::Muls(buf4, buf7, -2.0f, count);         // buf4 = -2*Spence_01
        AscendC::Muls(buf5, buf3, -HALF, count);         // buf5 = -0.5*ln_x_sq
        AscendC::Add(buf4, buf4, buf5, count);           // buf4 = -2*Spence_01 - 0.5*ln_x_sq
        AscendC::Adds(buf5, buf4, PI_SQ_DIV_3, count);   // buf5 = correctionGt1

        // result = Spence_01 + maskGt1 * correctionGt1
        AscendC::Mul(buf4, buf1, buf5, count);           // buf4 = maskGt1 * correctionGt1
        AscendC::Add(buf5, buf7, buf4, count);           // buf5 = final result (float32)

        // ===== Write output =====
        if constexpr (sizeof(T) == sizeof(float)) {
            // float32: 直接将结果写入 yLocal
            AscendC::Add(yLocal, buf5, buf5, count);     // yLocal = result (dummy 2*buf5, overwrite below)
            AscendC::Sub(yLocal, buf5, buf4, count);
        } else {
            // float16: 降精度并写入 yLocal
            AscendC::Cast(yLocal, buf5, AscendC::RoundMode::CAST_ROUND, count);
        }

        outQueueY.EnQue<T>(yLocal);
        inQueueX.FreeTensor(xLocal);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
        AscendC::DataCopy(yGm[progress * this->tileLength], yLocal, curTileLength);
        outQueueY.FreeTensor(yLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf0;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf1;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf2;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf3;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf4;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf5;
