// ============================================================
// Spence (Dilogarithm) 算子 op_kernel
// 使用算术mask替代Compare/Select避免Ascend910B3兼容性问题
// ============================================================

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// 常量
constexpr float EPS = 1e-10f;
constexpr float PI_SQ_DIV_6 = 1.6449340668482264f;
constexpr float PI_SQ_DIV_3 = 3.289868133696453f;
constexpr float HALF = 0.5f;
constexpr float ONE = 1.0f;
constexpr float NEG_HALF = -0.5f;
constexpr float NEG_ONE = -1.0f;
constexpr float ZERO = 0.0f;

// 多项式系数 c_k = 1/(k+1)^2，共20项
constexpr float COEFFS[20] = {
    1.0f,
    0.25f,
    0.111111111f,
    0.0625f,
    0.04f,
    0.027777778f,
    0.020408163f,
    0.015625f,
    0.012345679f,
    0.01f,
    0.008264463f,
    0.006944444f,
    0.005917160f,
    0.005102041f,
    0.004444444f,
    0.00390625f,
    0.003460208f,
    0.003086420f,
    0.002770083f,
    0.0025f
};

template <typename T>
class KernelSpence {
public:
    __aicore__ inline KernelSpence() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
        }

        this->tileLength = tileLength;

        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(tmpBuf0, tileLength * sizeof(float));
        pipe.InitBuffer(tmpBuf1, tileLength * sizeof(float));
        pipe.InitBuffer(tmpBuf2, tileLength * sizeof(float));
        pipe.InitBuffer(tmpBuf3, tileLength * sizeof(float));
        pipe.InitBuffer(tmpBuf4, tileLength * sizeof(float));
        pipe.InitBuffer(tmpBuf5, tileLength * sizeof(float));
        pipe.InitBuffer(tmpBuf6, tileLength * sizeof(float));
        pipe.InitBuffer(tmpBuf7, tileLength * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tileNum > 0) {
            CopyIn(tileNum - 1, alignedTailLen);
            Compute(tileNum - 1, alignedTailLen);
            CopyOut(tileNum - 1, alignedTailLen);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, static_cast<T>(0)};
        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], copyParams, padParams);
        inQueueX.EnQue(xLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();

        int32_t count = static_cast<int32_t>(curTileLength);

        if constexpr (sizeof(T) == sizeof(float)) {
            // FP32 path: use xLocal directly as float32 input
            AscendC::LocalTensor<float> xFp32 = xLocal;
            ComputeSpence(xFp32, yLocal, count);
        } else {
            // FP16 path: cast to fp32, compute, cast back
            AscendC::LocalTensor<float> xFp32 = tmpBuf0.Get<float>();
            AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, count);
            AscendC::LocalTensor<float> yFp32 = tmpBuf1.Get<float>();
            ComputeSpence(xFp32, yFp32, count);
            AscendC::Cast(yLocal, yFp32, AscendC::RoundMode::CAST_ROUND, count);
        }

        outQueueY.EnQue<T>(yLocal);
        inQueueX.FreeTensor(xLocal);
    }

    __aicore__ inline void ComputeSpence(
        AscendC::LocalTensor<float> &xLocalFp32,
        AscendC::LocalTensor<float> &yLocalFp32,
        int32_t count)
    {
        AscendC::LocalTensor<float> buf0 = tmpBuf2.Get<float>();
        AscendC::LocalTensor<float> buf1 = tmpBuf3.Get<float>();
        AscendC::LocalTensor<float> buf2 = tmpBuf4.Get<float>();
        AscendC::LocalTensor<float> buf3 = tmpBuf5.Get<float>();
        AscendC::LocalTensor<float> buf4 = tmpBuf6.Get<float>();
        AscendC::LocalTensor<float> buf5 = tmpBuf7.Get<float>();

        // ===== Step 1: small = Min(x, 1/max(x, eps)) =====
        // buf0 = max(x, eps)
        AscendC::Maxs(buf0, xLocalFp32, EPS, count);
        // buf1 = 1 / buf0
        AscendC::Reciprocal(buf1, buf0, count);
        // buf2 = small = min(x, 1/x)
        AscendC::Min(buf2, xLocalFp32, buf1, count);

        // ===== Step 2: a = Min(small, 1-small), oneMinusSmall = 1-small =====
        // buf3 = -small + 1 = 1-small
        AscendC::Muls(buf3, buf2, NEG_ONE, count);
        AscendC::Adds(buf3, buf3, ONE, count);
        // buf4 = a = min(small, 1-small)
        AscendC::Min(buf4, buf2, buf3, count);

        // ===== Step 3: Horner polynomial for Li₂(a) =====
        // buf5 = acc = c_19
        AscendC::Duplicate(buf5, COEFFS[19], count);
        for (int k = 18; k >= 0; --k) {
            // buf1 = a * acc
            AscendC::Mul(buf1, buf4, buf5, count);
            // buf5 = c_k + a*acc
            AscendC::Adds(buf5, buf1, COEFFS[k], count);
        }
        // buf5 = a * P(a) = Li₂(a)
        AscendC::Mul(buf5, buf4, buf5, count);

        // buf5 = Li₂(a), buf2 = small, buf4 = a

        // ===== Step 4: [0.5, 1] Euclidean reflection for Li₂ =====
        // mask = (max(small,0.5)-0.5) / (max(small,0.5)-min(small,0.5)+eps)
        AscendC::Maxs(buf0, buf2, HALF, count);        // buf0 = xH
        AscendC::Mins(buf1, buf2, HALF, count);        // buf1 = xL
        AscendC::Sub(buf4, buf0, buf1, count);         // buf4 = xH - xL
        AscendC::Adds(buf4, buf4, EPS, count);         // buf4 = den
        AscendC::Adds(buf0, buf0, NEG_HALF, count);    // buf0 = num = xH - 0.5
        AscendC::Div(buf0, buf0, buf4, count);         // buf0 = maskHalf

        // lnProd = ln(max(small,eps)) * ln(max(oneMinusSmall,eps))
        AscendC::Maxs(buf1, buf2, EPS, count);         // buf1 = safe(small)
        AscendC::Ln(buf1, buf1, count);                // buf1 = ln(small)
        AscendC::Maxs(buf4, buf3, EPS, count);         // buf4 = safe(oneMinusSmall)
        AscendC::Ln(buf4, buf4, count);                // buf4 = ln(oneMinusSmall)
        AscendC::Mul(buf3, buf1, buf4, count);         // buf3 = ln(small)*ln(oneMinusSmall)

        // correctionHalf = PI_SQ_DIV_6 - lnProd - 2*Li₂_a
        AscendC::Muls(buf1, buf5, -2.0f, count);       // buf1 = -2*Li₂_a
        AscendC::Sub(buf1, buf1, buf3, count);         // buf1 = -2*Li₂_a - lnProd
        AscendC::Adds(buf1, buf1, PI_SQ_DIV_6, count); // buf1 = correctionHalf

        // Li₂_01 = Li₂_a + maskHalf * correctionHalf
        AscendC::Mul(buf3, buf0, buf1, count);         // buf3 = maskHalf * correctionHalf
        AscendC::Add(buf0, buf5, buf3, count);         // buf0 = Li₂_01

        // ===== Step 5: x > 1 global reflection for Li₂ =====
        // mask = (max(x,1.0)-1.0) / (max(x,1.0)-min(x,1.0)+eps)
        AscendC::Maxs(buf1, xLocalFp32, ONE, count);    // buf1 = xH
        AscendC::Mins(buf2, xLocalFp32, ONE, count);    // buf2 = xL
        AscendC::Sub(buf3, buf1, buf2, count);          // buf3 = xH - xL
        AscendC::Adds(buf3, buf3, EPS, count);          // buf3 = den
        AscendC::Adds(buf1, buf1, NEG_ONE, count);     // buf1 = num = xH - 1.0
        AscendC::Div(buf1, buf1, buf3, count);          // buf1 = maskGt1

        // ln_x_sq = ln(max(x, eps))^2
        AscendC::Maxs(buf2, xLocalFp32, EPS, count);    // buf2 = max(x, eps)
        AscendC::Ln(buf2, buf2, count);                 // buf2 = ln(x)
        AscendC::Mul(buf2, buf2, buf2, count);          // buf2 = ln_x_sq

        // correctionGt1 = PI_SQ_DIV_3 - 0.5*ln_x_sq - 2*Li₂_01
        AscendC::Muls(buf3, buf0, -2.0f, count);        // buf3 = -2*Li₂_01
        AscendC::Muls(buf4, buf2, NEG_HALF, count);      // buf4 = -0.5*ln_x_sq
        AscendC::Add(buf3, buf3, buf4, count);          // buf3 = -2*Li₂_01 - 0.5*ln_x_sq
        AscendC::Adds(buf3, buf3, PI_SQ_DIV_3, count);  // buf3 = correctionGt1

        // result = Li₂_01 + maskGt1 * correctionGt1
        AscendC::Mul(buf4, buf1, buf3, count);          // buf4 = maskGt1 * correctionGt1
        AscendC::CopyPar(buf2, buf0, count);            // buf2 = Li₂_01 (copy)
        AscendC::Add(yLocalFp32, buf2, buf4, count);     // yLocalFp32 = result
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(yGm[progress * this->tileLength], yLocal, copyParams);
        outQueueY.FreeTensor(yLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf0;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf1;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf2;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf3;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf4;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf5;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf6;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf7;
    AscendC::GlobalTensor<T> xGm;
    AscendC::GlobalTensor<T> yGm;
    int64_t blockLength;
    int64_t tileLength;
};

extern "C" __global__ __aicore__ void spence(GM_ADDR x, GM_ADDR y,
                                               int64_t formerNum, int64_t formerLength,
                                               int64_t tailLength, int64_t tileLength,
                                               int64_t dtypeSize)
{
    if (dtypeSize == 2) {
        KernelSpence<half> op;
        op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else {
        KernelSpence<float> op;
        op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    }
}
