// Spence(x) = Li₂(1-x) where Li₂ is the standard dilogarithm
// For x in [0,1]: spence(x) = Li₂(1-x)
// For x > 1:      spence(x) = -0.5*ln²(x) - Li₂((x-1)/x)
// Arithmetic masks used instead of Compare/Select

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

constexpr float EPS        = 1e-10f;
constexpr float PI_SQ_DIV_6 = 1.6449340668482264f;
constexpr float HALF        = 0.5f;
constexpr float ONE         = 1.0f;
constexpr float NEG_ONE     = -1.0f;
constexpr float NEG_TWO     = -2.0f;

constexpr float COEFFS[20] = {
    1.0f, 0.25f, 0.111111111f, 0.0625f, 0.04f,
    0.027777778f, 0.020408163f, 0.015625f, 0.012345679f, 0.01f,
    0.008264463f, 0.006944444f, 0.005917160f, 0.005102041f, 0.004444444f,
    0.00390625f, 0.003460208f, 0.003086420f, 0.002770083f, 0.0025f
};

template <typename T>
class KernelSpence {
public:
    __aicore__ inline KernelSpence() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();
        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
        }
        this->tileLength = tileLength;
        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(tmpBuf0, tileLength * sizeof(float));
        pipe.InitBuffer(tmpBuf1, tileLength * sizeof(float));
        pipe.InitBuffer(tmpBuf2, tileLength * sizeof(float));
        pipe.InitBuffer(tmpBuf3, tileLength * sizeof(float));
        pipe.InitBuffer(tmpBuf4, tileLength * sizeof(float));
        pipe.InitBuffer(tmpBuf5, tileLength * sizeof(float));
        pipe.InitBuffer(tmpBuf6, tileLength * sizeof(float));
        pipe.InitBuffer(tmpBuf7, tileLength * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        int64_t tN = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailT = this->blockLength - (tN - 1) * this->tileLength;
        int64_t align = 32 / static_cast<int64_t>(sizeof(T));
        int64_t aTail = ((tailT + align - 1) / align) * align;
        for (int64_t i = 0; i < tN - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tN > 0) {
            CopyIn(tN - 1, aTail);
            Compute(tN - 1, aTail);
            CopyOut(tN - 1, aTail);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        AscendC::DataCopyExtParams cp{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> pp{false, 0, 0, static_cast<T>(0)};
        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], cp, pp);
        inQueueX.EnQue(xLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xL = inQueueX.DeQue<T>();
        AscendC::LocalTensor<T> yL = outQueueY.AllocTensor<T>();
        int32_t n = static_cast<int32_t>(curTileLength);

        if constexpr (sizeof(T) == sizeof(float)) {
            ComputeSpenceFp32(xL, yL, n);
        } else {
            AscendC::LocalTensor<float> x32 = tmpBuf0.Get<float>();
            AscendC::LocalTensor<float> y32 = tmpBuf1.Get<float>();
            AscendC::Cast(x32, xL, AscendC::RoundMode::CAST_NONE, n);
            ComputeSpenceFp32(x32, y32, n);
            AscendC::Cast(yL, y32, AscendC::RoundMode::CAST_ROUND, n);
        }
        outQueueY.EnQue<T>(yL);
        inQueueX.FreeTensor(xL);
    }

    // Li₂(q) on [0,1] using polynomial + Euclidean reflection
    // Returns Li₂(q) in buf0
    __aicore__ inline void Li2On01(
        AscendC::LocalTensor<float> &q,
        AscendC::LocalTensor<float> &buf0,
        AscendC::LocalTensor<float> &buf1,
        AscendC::LocalTensor<float> &buf2,
        AscendC::LocalTensor<float> &buf3,
        AscendC::LocalTensor<float> &buf4,
        AscendC::LocalTensor<float> &buf5,
        int32_t n)
    {
        // a = min(q, 1-q), 1-q = buf3, a = buf4
        AscendC::Muls(buf3, q, NEG_ONE, n);
        AscendC::Adds(buf3, buf3, ONE, n);
        AscendC::Min(buf4, q, buf3, n);

        // Horner: Li₂(a) ≈ a * P(a), using 20 coefficients
        AscendC::Duplicate(buf5, COEFFS[19], n);
        for (int k = 18; k >= 0; --k) {
            AscendC::Mul(buf1, buf4, buf5, n);
            AscendC::Adds(buf5, buf1, COEFFS[k], n);
        }
        AscendC::Mul(buf5, buf4, buf5, n);  // buf5 = Li₂(a)

        // mask half: (max(q,0.5)-0.5)/(max(q,0.5)-min(q,0.5)+eps)
        AscendC::Maxs(buf0, q, HALF, n);
        AscendC::Mins(buf1, q, HALF, n);
        AscendC::Sub(buf4, buf0, buf1, n);
        AscendC::Adds(buf4, buf4, EPS, n);            // den
        AscendC::Adds(buf0, buf0, -HALF, n);          // num = xH-0.5
        AscendC::Div(buf0, buf0, buf4, n);            // maskHalf

        // lnProd = ln(q)*ln(1-q)
        AscendC::Maxs(buf1, q, EPS, n);
        AscendC::Ln(buf1, buf1, n);
        AscendC::Maxs(buf4, buf3, EPS, n);
        AscendC::Ln(buf4, buf4, n);
        AscendC::Mul(buf2, buf1, buf4, n);            // buf2 = lnProd

        // correction = PI_SQ_DIV_6 - lnProd - 2*Li₂(a)
        AscendC::Muls(buf1, buf5, NEG_TWO, n);        // -2*Li₂(a)
        AscendC::Sub(buf1, buf1, buf2, n);            // -2*Li₂(a) - lnProd
        AscendC::Adds(buf1, buf1, PI_SQ_DIV_6, n);    // correction

        // Li₂(q) = Li₂(a) + maskHalf * correction
        AscendC::Mul(buf2, buf0, buf1, n);            // mask * correction
        AscendC::Add(buf0, buf5, buf2, n);            // buf0 = Li₂(q)
    }

    __aicore__ inline void ComputeSpenceFp32(
        AscendC::LocalTensor<float> &x,
        AscendC::LocalTensor<float> &y,
        int32_t n)
    {
        // Get TBufs
        auto& xFp32 = tmpBuf2.Get<float>();  // bx0: copy of x
        auto& bx1 = tmpBuf3.Get<float>();
        auto& bx2 = tmpBuf4.Get<float>();
        auto& bx3 = tmpBuf5.Get<float>();
        auto& bx4 = tmpBuf6.Get<float>();
        auto& bx5 = tmpBuf7.Get<float>();

        // Copy x to TBuf (we need x for later mask computation)
        AscendC::Adds(xFp32, x, 0.0f, n);

        // ===== maskGt1 for x > 1 =====
        AscendC::Maxs(bx1, xFp32, ONE, n);            // xH
        AscendC::Mins(bx2, xFp32, ONE, n);            // xL
        AscendC::Sub(bx3, bx1, bx2, n);               // xH - xL
        AscendC::Adds(bx3, bx3, EPS, n);              // den
        AscendC::Adds(bx1, bx1, NEG_ONE, n);          // num = xH-1
        AscendC::Div(bx1, bx1, bx3, n);               // maskGt1

        // ===== q = blended argument for Li₂ =====
        // q1 = 1-x, q2 = (x-1)/x
        // q = q1 + maskGt1 * (q2 - q1)
        AscendC::Muls(bx4, xFp32, NEG_ONE, n);        // -x
        AscendC::Adds(bx4, bx4, ONE, n);              // q1 = 1-x

        AscendC::Adds(bx3, xFp32, NEG_ONE, n);        // x-1
        AscendC::Maxs(bx5, xFp32, EPS, n);            // safe x
        AscendC::Div(bx3, bx3, bx5, n);               // q2 = (x-1)/x

        AscendC::Sub(bx3, bx3, bx4, n);               // q2 - q1
        AscendC::Mul(bx3, bx3, bx1, n);               // maskGt1 * (q2 - q1)
        AscendC::Add(bx3, bx4, bx3, n);               // q = q1 + mask*(q2-q1)

        // bx2 = q for Li₂ computation. Need original x again for ln.

        // ===== Li₂(q) on [0,1] =====
        Li2On01(bx3, bx2, bx4, bx5, bx3, bx2, bx4, n);
        // Wait - Li2On01 uses q, and stores result in buf0 (which was the q buffer!).
        // Let me redo. Li2On01 needs to receive buffers carefully.

        // Actually, let me re-invoke with correct buffers.
        // I need: q (input), and 6 temp buffers. Output goes to the last buffer.
        // Current buffers: bx2, bx4, bx5... hmm, I overwrite them.

        // Let me redo the Li₂(q) computation inline for clarity.
        // a = min(q, 1-q)
        AscendC::Muls(bx4, bx3, NEG_ONE, n);
        AscendC::Adds(bx4, bx4, ONE, n);
        AscendC::Min(bx5, bx3, bx4, n);               // bx5 = a

        // Horner
        AscendC::Duplicate(bx2, COEFFS[19], n);
        for (int k = 18; k >= 0; --k) {
            AscendC::Mul(bx5, bx5, bx2, n);
            AscendC::Adds(bx2, bx5, COEFFS[k], n);
        }
        AscendC::Mul(bx2, bx5, bx2, n);  // bx2 = Li₂(a)

        // maskHalf
        AscendC::Maxs(xFp32, bx3, HALF, n);  // reuse xFp32 as temp (x no longer needed)
        // Wait, xFp32 is being reused but I might still need x for ln²...

        // Actually, I need x for the correction formula: correction_gt1 = -2*Li₂_q - 0.5*ln²(x)
        // And I need to compute ln²(x) using xFp32. If I reuse xFp32, I lose x.
        // But I already have x saved in bx... no, xFp32 IS the copy of x.

        // Hmm, let me save x before using it. Actually, I compute ln_x_sq BEFORE the Li₂ mask computation:
        // ln_x_sq = ln(max(x, eps))^2
        AscendC::Maxs(xFp32, xFp32, EPS, n);
        AscendC::Ln(xFp32, xFp32, n);
        AscendC::Mul(xFp32, xFp32, xFp32, n);  // xFp32 = ln_x_sq

        // Now xFp32 is ln²(x). But I need the original x for nothing else.

        // Wait, x was the input. The maskGt1 was already computed and stored in bx1.
        // q was computed as bx3. ln_x_sq is in xFp32.
        // I no longer need the original x value.

        // maskHalf computation (using buf buffers):
        AscendC::Maxs(bx4, bx3, HALF, n);
        AscendC::Mins(bx5, bx3, HALF, n);
        AscendC::Sub(bx4, bx4, bx5, n);
        AscendC::Adds(bx4, bx4, EPS, n);              // den
        AscendC::Adds(bx5, bx4, NEG_ONE, n);          // reuse bx5 as num, but I need xH!

        // Hmm, xH was in bx4 but I overwrote it. Let me redo.
        // Actually: Add(xH - hal) needs xH. Let me save or recompute.

        // Remake: maskHalf(xH, xL)
        AscendC::Maxs(bx4, bx3, HALF, n);            // bx4 = xH
        AscendC::Mins(bx5, bx3, HALF, n);            // bx5 = xL
        // num = xH - 0.5 = bx4 - 0.5, store temporarily
        AscendC::Adds(bx2, bx4, -HALF, n);           // bx2 = num (overwrite Li₂(a) in bx2!!)

        // Whoa! This overwrites Li₂(a) which I need later!
        // I need to be more careful with buffer management.

        // Let me redo the entire thing. I have 6 TBuf + the original x and y.
        // Actually I have access to tmpBuf0(tmpBuf2-7) for computation.
        // Let me write a clearer implementation.
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
        AscendC::DataCopyExtParams cp{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(yGm[progress * this->tileLength], yLocal, cp);
        outQueueY.FreeTensor(yLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf0;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf1;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf2;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf3;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf4;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf5;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf6;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf7;
    AscendC::GlobalTensor<T> xGm;
    AscendC::GlobalTensor<T> yGm;
    int64_t blockLength;
    int64_t tileLength;
};
