    0.027777778f, 0.020408163f, 0.015625f, 0.012345679f, 0.01f,
    0.008264463f, 0.006944444f, 0.005917160f, 0.005102041f, 0.004444444f,
    0.00390625f, 0.003460208f, 0.003086420f, 0.002770083f, 0.0025f
};

template <typename T>
class KernelSpence {
public:
    __aicore__ inline KernelSpence() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength)
    {
        int64_t blockIdx = AscendC::GetBlockIdx();
        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
        }
        this->tileLength = tileLength;
        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(tmp0, tileLength * sizeof(float));
        pipe.InitBuffer(tmp1, tileLength * sizeof(float));
        pipe.InitBuffer(tmp2, tileLength * sizeof(float));
        pipe.InitBuffer(tmp3, tileLength * sizeof(float));
        pipe.InitBuffer(tmp4, tileLength * sizeof(float));
        pipe.InitBuffer(tmp5, tileLength * sizeof(float));
        pipe.InitBuffer(tmp6, tileLength * sizeof(float));
        pipe.InitBuffer(tmp7, tileLength * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        int64_t tN = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailT = this->blockLength - (tN - 1) * this->tileLength;
        int64_t align = 32 / static_cast<int64_t>(sizeof(T));
        int64_t aTail = ((tailT + align - 1) / align) * align;
        for (int64_t i = 0; i < tN - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tN > 0) {
            CopyIn(tN - 1, aTail);
            Compute(tN - 1, aTail);
            CopyOut(tN - 1, aTail);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xL = inQueueX.AllocTensor<T>();
        AscendC::DataCopyExtParams cp{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> pp{false, 0, 0, static_cast<T>(0)};
        AscendC::DataCopyPad(xL, xGm[progress * this->tileLength], cp, pp);
        inQueueX.EnQue(xL);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xL = inQueueX.DeQue<T>();
        AscendC::LocalTensor<T> yL = outQueueY.AllocTensor<T>();
        int32_t n = static_cast<int32_t>(curTileLength);

        if constexpr (sizeof(T) == sizeof(float)) {
            // FP32: compute directly
            AscendC::LocalTensor<float> b0 = tmp0.Get<float>();  // x copy
            AscendC::LocalTensor<float> b1 = tmp1.Get<float>();
            AscendC::LocalTensor<float> b2 = tmp2.Get<float>();
            AscendC::LocalTensor<float> b3 = tmp3.Get<float>();
            AscendC::LocalTensor<float> b4 = tmp4.Get<float>();
            AscendC::LocalTensor<float> b5 = tmp5.Get<float>();
            AscendC::Adds(b0, xL, 0.0f, n);
            SpenceImpl(b0, b1, b2, b3, b4, b5, yL, n);
        } else {
            // FP16: cast to fp32, compute, cast back
            AscendC::LocalTensor<float> b0 = tmp0.Get<float>();
            AscendC::LocalTensor<float> b1 = tmp1.Get<float>();
            AscendC::LocalTensor<float> b2 = tmp2.Get<float>();
            AscendC::LocalTensor<float> b3 = tmp3.Get<float>();
            AscendC::LocalTensor<float> b4 = tmp4.Get<float>();
            AscendC::LocalTensor<float> b5 = tmp5.Get<float>();
            AscendC::LocalTensor<float> r32 = tmp6.Get<float>();
            AscendC::Cast(b0, xL, AscendC::RoundMode::CAST_NONE, n);
            SpenceImpl(b0, b1, b2, b3, b4, b5, r32, n);
            AscendC::Cast(yL, r32, AscendC::RoundMode::CAST_ROUND, n);
        }
        outQueueY.EnQue<T>(yL);
        inQueueX.FreeTensor(xL);
    }

    // Core Spence implementation: y = spence(x) where b0 = x (float32)
    // b0-b5 are temp buffers (modified), y is output
    __aicore__ inline void SpenceImpl(
        AscendC::LocalTensor<float> &b0,   // b0 = x (destroyed)
        AscendC::LocalTensor<float> &b1,
        AscendC::LocalTensor<float> &b2,
        AscendC::LocalTensor<float> &b3,
        AscendC::LocalTensor<float> &b4,
        AscendC::LocalTensor<float> &b5,
        AscendC::LocalTensor<float> &y,
        int32_t n)
    {
        // ---- Step 1: ln²(x) ----
        AscendC::Maxs(b1, b0, EPS, n);    // b1 = max(x, eps)
        AscendC::Ln(b1, b1, n);           // b1 = ln(x)
        AscendC::Mul(b1, b1, b1, n);      // b1 = ln²(x)         [KEEP]

        // ---- Step 2: maskGt1 = (max(x,1)-1)/(max(x,1)-min(x,1)+eps) ----
        AscendC::Maxs(b2, b0, 1.0f, n);   // b2 = xH = max(x,1)
        AscendC::Mins(b3, b0, 1.0f, n);   // b3 = xL = min(x,1)
        AscendC::Sub(b4, b2, b3, n);      // b4 = xH - xL
        AscendC::Adds(b4, b4, EPS, n);    // b4 = den               [tmp]
        AscendC::Adds(b2, b2, -1.0f, n);  // b2 = num = xH-1        [maskGt1]
        AscendC::Div(b2, b2, b4, n);      // b2 = maskGt1           [KEEP]
        // b3, b4 free

        // ---- Step 3: q1 = 1-x, q2 = (x-1)/max(x,eps) ----
        AscendC::Muls(b3, b0, -1.0f, n);
        AscendC::Adds(b3, b3, 1.0f, n);   // b3 = q1 = 1-x

        AscendC::Adds(b4, b0, -1.0f, n);  // b4 = x-1
        AscendC::Maxs(b5, b0, EPS, n);    // b5 = max(x, eps)
        AscendC::Div(b4, b4, b5, n);      // b4 = q2 = (x-1)/x
        // b5 free

        // ---- Step 4: q = q1 + maskGt1*(q2-q1) ----
        AscendC::Sub(b5, b4, b3, n);      // b5 = q2 - q1
        AscendC::Mul(b5, b5, b2, n);      // b5 = maskGt1 * (q2-q1)
        AscendC::Add(b3, b3, b5, n);      // b3 = q = q1 + mask*(q2-q1)  [KEEP]
        // b4 free, b5 free

        // ---- Step 5: a = min(q, 1-q),  Li₂(a) via Horner ----
        AscendC::Muls(b4, b3, -1.0f, n);
        AscendC::Adds(b4, b4, 1.0f, n);   // b4 = 1-q
        AscendC::Min(b5, b3, b4, n);      // b5 = a = min(q,1-q)  [KEEP]

        AscendC::Duplicate(b0, COEFFS[19], n);  // b0 = acc = c_19 (overwrite x)
        for (int k = 18; k >= 0; --k) {
            AscendC::Mul(b4, b5, b0, n);         // b4 = a * acc
            AscendC::Adds(b0, b4, COEFFS[k], n); // b0 = c_k + a*acc
        }
        AscendC::Mul(b0, b5, b0, n);      // b0 = Li₂(a)         [KEEP]
        // b4 free, b5 keeps a (may reuse)

        // ---- Step 6: maskHalf, correction, Li₂(q) ----
        // maskHalf = (max(q,0.5)-0.5)/(max(q,0.5)-min(q,0.5)+eps)
        AscendC::Maxs(b4, b3, 0.5f, n);   // b4 = xH
        AscendC::Mins(b5, b3, 0.5f, n);   // b5 = xL  (overwrite a)
        AscendC::Sub(b5, b4, b5, n);      // b5 = xH - xL = den_tmp
        AscendC::Adds(b5, b5, EPS, n);    // b5 = den
        AscendC::Adds(b4, b4, -0.5f, n);  // b4 = num = xH-0.5
        AscendC::Div(b4, b4, b5, n);      // b4 = maskHalf        [KEEP]
        // b5 free

        // lnProd = ln(max(q,eps)) * ln(max(1-q,eps))
        AscendC::Muls(b5, b3, -1.0f, n);  // b5 = -q
        AscendC::Adds(b5, b5, 1.0f, n);   // b5 = 1-q
        AscendC::Maxs(b5, b5, EPS, n);    // b5 = safe(1-q)
        AscendC::Ln(b5, b5, n);           // b5 = ln(1-q)
        AscendC::Maxs(b3, b3, EPS, n);    // b3 = safe(q) (modify q in place)
        AscendC::Ln(b3, b3, n);           // b3 = ln(q)
        AscendC::Mul(b3, b3, b5, n);      // b3 = lnProd          [KEEP]
        // b5 free

        // correctionHalf = PI_SQ_D6 - lnProd - 2*Li₂(a)
        AscendC::Muls(b5, b0, -2.0f, n);  // b5 = -2*Li₂(a)
        AscendC::Sub(b5, b5, b3, n);      // b5 = -2*Li₂(a) - lnProd
        AscendC::Adds(b5, b5, PI_SQ_D6, n); // b5 = correctionHalf

        // Li₂(q) = Li₂(a) + maskHalf * correctionHalf
        AscendC::Mul(b3, b4, b5, n);      // b3 = maskHalf * corr (overwrite lnProd)
        AscendC::Add(b0, b0, b3, n);      // b0 = Li₂(q)         [KEEP]
        // b3, b4, b5 free

        // ---- Step 7: final = Li₂(q) + maskGt1*(-2*Li₂(q) - 0.5*ln²(x)) ----
        // correctionGt1 = -2*Li₂(q) - 0.5*ln²(x)
        AscendC::Muls(b3, b0, -2.0f, n);  // b3 = -2*Li₂(q)
        AscendC::Muls(b4, b1, -0.5f, n);  // b4 = -0.5*ln²(x)
        AscendC::Add(b3, b3, b4, n);      // b3 = correctionGt1
        // b4 free

        // result = Li₂(q) + maskGt1 * correctionGt1
        AscendC::Mul(b4, b2, b3, n);      // b4 = maskGt1 * correctionGt1
        AscendC::Add(y, b0, b4, n);       // y = Li₂(q) + mask * corr = spence(x)
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> yL = outQueueY.DeQue<T>();
        AscendC::DataCopyExtParams cp{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(yGm[progress * this->tileLength], yL, cp);
        outQueueY.FreeTensor(yL);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmp0;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmp1;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmp2;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmp3;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmp4;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmp5;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmp6;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmp7;
    AscendC::GlobalTensor<T> xGm;
    AscendC::GlobalTensor<T> yGm;
    int64_t blockLength;
    int64_t tileLength;
};

extern "C" __global__ __aicore__ void spence(GM_ADDR x, GM_ADDR y,
                                               int64_t formerNum, int64_t formerLength,
                                               int64_t tailLength, int64_t tileLength,
                                               int64_t dtypeSize)
{
    if (dtypeSize == 2) {
        KernelSpence<half> op;
        op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    } else {
        KernelSpence<float> op;
        op.Init(x, y, formerNum, formerLength, tailLength, tileLength);
        op.Process();
    }
}
